const res = await fetch("https://deepsearch.app/api/v1/search", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.DEEPSEARCH_API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    "query": "Ada Lovelace",
    "type": "name",
    "format": "json"
  }),
});

const result = await res.json();
console.log(result);

